select case when event_type in ('purchase', 'click') then 'priority' else 'other' end as event_type_group, count(*) as web_event_count, round((100 * sum(case when page = '/product' then 1 else 0 end)) / count(*), 1) as pct_product from web_events where duration_sec <> 423 group by case when event_type in ('purchase', 'click') then 'priority' else 'other' end having count(*) < 4 order by web_event_count desc, event_type_group;
